const {topics,cases,lessons}=COURSE;
const {score,parseCommand,matchTopics,normalize}=TrainerEngine;
const modes=[['Leer','↳','Begrijp een onderwerp. Kort uitgelegd, daarna jouw beurt.'],['Overhoor','?','Open vragen. Laat zien wat je zonder spieken weet.'],['Quiz','✓','Meerkeuzevragen. Kies je antwoord en krijg direct uitleg.'],['Battle','↗','Neem positie. De jury valt je redenering aan.'],['Gatenlijst','◎','Zie wat je miste en pak gericht de stof erbij.']];
let state;try{state=JSON.parse(localStorage.getItem('han-battle-v1'))}catch{}state=state&&state.version===1?state:{version:1,history:[],gaps:[],notes:[],round:null};
state.quizHistory=Array.isArray(state.quizHistory)?state.quizHistory:[];
if(state.round&&!modes.some(m=>m[0]===state.round.mode))state.round=null;
let page='home',mode='Overhoor',filter='alles',subject='alles',round=state.round,message='',questionCursor={};
const app=document.querySelector('#app');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const getTopic=id=>topics.find(t=>t.id===id);
const getLesson=id=>lessons.find(l=>l.id===id);
function persist(){state.round=round;try{localStorage.setItem('han-battle-v1',JSON.stringify(state));document.querySelector('#gap-count').textContent=state.gaps.length}catch{document.querySelector('.sidebar-bottom').textContent='Opslaan lukt niet. Houd deze pagina open.'}}
const refButton=id=>`<button class="tag" data-source="${id}">${escape(getLesson(id).ref)} ↗</button>`;
function heading(k,title,text){return `<div class="eyebrow">${k}</div><h1>${title}</h1>${text?`<p style="color:var(--muted)">${text}</p>`:''}`}
function navigate(next){page=next;message='';render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#gap-count').textContent=state.gaps.length;if(page==='home')home();else if(page==='train')training();else if(page==='sources')sources();else if(page==='gaps')gaps();else if(page==='scores')scores();else if(page==='menu')menu();bind();}
function home(){const done=new Set([...state.history,...state.quizHistory].map(h=>h.topic));const remaining=Math.max(0,Math.ceil((new Date('2026-10-15T00:00:00+02:00')-Date.now())/86400000));app.innerHTML=`<div class="intro"><div>${heading('DE BATTLE KOMT ERAAN','Maak je kennis<br>juryproof.','Ken de stof. Onderbouw je punt. Houd stand als de jury doorvraagt.')}</div><span class="date-pill">${remaining>0?`Nog ${remaining} dagen tot de Battle`:'Battle · 15 oktober 2026'}</span></div><div class="layout"><div><section class="hero"><div class="hero-content"><div class="eyebrow">HET IS JOUW BEURT</div><h2>Een goed verhaal<br>begint bij de stof.</h2><p>Oefen met echte cases. Verbind duurzaamheid aan business ethics en ontdek waar je kennis nog hapert.</p><button class="btn primary" data-mode="Battle">Start een Battle <span>↗</span></button></div><svg class="orbit" viewBox="0 0 220 220" aria-hidden="true"><circle cx="110" cy="110" r="90"/><circle cx="110" cy="110" r="62"/><ellipse cx="110" cy="110" rx="100" ry="35" transform="rotate(-40 110 110)"/><ellipse cx="110" cy="110" rx="100" ry="35" transform="rotate(40 110 110)"/><circle class="core" cx="110" cy="110" r="36"/><text x="94" y="121">↗</text><circle class="core" cx="48" cy="46" r="7"/><circle class="core" cx="191" cy="148" r="5"/></svg></section><div class="section-head"><h2>Kies je oefenvorm</h2><span>Van begrijpen naar verdedigen</span></div><div class="mode-grid">${modes.map(m=>`<button class="mode-card" data-mode="${m[0]}"><span class="mode-icon">${m[1]}</span><span class="arrow">↗</span><h3>${m[0]}</h3><p>${m[2]}</p></button>`).join('')}</div>${commandForm()}<p class="saved-note">Bijvoorbeeld: Overhoor greenwashing · Battle R-ladder · Leer systeemdenken</p>${round?`<button class="btn quiet" id="resume">Hervat je oefenronde →</button>`:''}</div><aside class="right-rail"><section class="panel"><div class="eyebrow">OP DE AGENDA</div><div class="calendar"><span class="day">15</span><div><b>Oktober 2026</b><small>Donderdag · de Battle</small></div></div><p>Een spelshow, een debat en een jury die alles onderuit haalt. Bereid je voor op doorvragen.</p><ol class="steps"><li><b>1</b><span>Ken je begrippen<small>Leg het uit in je eigen woorden.</small></span></li><li><b>2</b><span>Breng bewijs mee<small>Gebruik een case uit de stof.</small></span></li><li><b>3</b><span>Verbind de kaders<small>Duurzaamheid én business ethics.</small></span></li></ol></section><section class="panel"><div class="eyebrow">JOUW VOORBEREIDING</div><div class="progress-row"><span>Onderwerpen geoefend</span><b>${done.size} / 14</b></div><div class="track"><i style="width:${done.size/14*100}%"></i></div><p style="margin-top:14px">${state.history.length} open rondes · ${state.quizHistory.length} quizvragen · ${state.gaps.length} open aandachtspunten</p><button class="btn quiet" data-page="scores">Bekijk voortgang ↗</button></section><div class="notice"><b>Oefenen met zelfbeoordeling</b><br>Bij open vragen beoordeel je jezelf aan de stof. De Quiz controleert je keuze automatisch. Er is geen AI-beoordelaar gekoppeld.</div></aside></div>`;}
function commandForm(){return `<form class="command-form"><span>⌘</span><label class="sr-only" for="command">Typ een commando of zoek in de stof</label><input id="command" placeholder="Typ een commando of zoek in de stof…" autocomplete="off"><button aria-label="Commando uitvoeren">→</button></form>`;}
function pool(){return topics.filter(t=>(filter==='alles'||t.id[0]===filter)&&(subject==='alles'||t.id===subject));}
function begin(selectedMode,query=''){if(selectedMode==='Gatenlijst')return navigate('gaps');mode=selectedMode;if(query&&query!=='alles'){let found=matchTopics(topics,query);if(!found.length){message=`Geen onderwerp gevonden voor “${query}”. Zoek in de bronnen of kies een onderwerp uit de lijst.`;page='train';round=null;render();return}subject=found[0].id;filter='alles';}else subject='alles';page='train';nextRound();}
function nextRound(){if(mode==='Quiz'){nextQuiz();return}let available=pool();if(!available.length){message='Er zijn geen onderwerpen binnen deze selectie.';round=null;render();return}let candidates=available.filter(t=>t.id!==round?.topic);if(!candidates.length)candidates=available;let t=candidates[Math.floor(Math.random()*candidates.length)];let n=questionCursor[t.id]||0;questionCursor[t.id]=n+1;round={topic:t.id,mode,index:['Battle','Leer'].includes(mode)?0:n%2,phase:'answer',messages:[],answers:[],assessment:null};message='';let prompt=t.questions[round.index];if(mode==='Leer'){let example=cases.find(c=>c.lesson===t.id);let intro=t.intro;if(example&&!intro.includes(example.name))intro+=' Voorbeeld uit de stof: '+example.name+'.';addMessage('trainer',intro,t.id);prompt=t.questions[0];round.index=0;}if(mode==='Battle')prompt='Stelling: '+t.statement+'\nNeem positie en onderbouw je antwoord met de stof.';addMessage('trainer',prompt,t.id);persist();render();}
function addMessage(role,text,ref){round.messages.push({role,text,ref});}
function training(){if(mode==='Quiz'){quizTraining();return}let t=round?getTopic(round.topic):null;let chosen=topics.filter(t=>filter==='alles'||t.id[0]===filter);app.innerHTML=`<button class="back" data-page="home">← Terug naar de oefenarena</button><div class="training-title"><div>${heading('OEFENARENA · '+mode.toUpperCase(),mode==='Battle'?'Houd stand voor de jury.':mode==='Leer'?'Begrijp het. Pas het toe.':'Wat weet je zonder spieken?')}</div><span class="tag">Zelfbeoordeling · zonder AI</span></div><div class="filters"><label>Vakgebied<select id="course-filter"><option value="alles">Beide vakgebieden</option><option value="d" ${filter==='d'?'selected':''}>Duurzaamheid</option><option value="e" ${filter==='e'?'selected':''}>Business ethics</option></select></label><label>Onderwerp<select id="topic-filter"><option value="alles">Alles · door elkaar</option>${chosen.map(t=>`<option value="${t.id}" ${subject===t.id?'selected':''}>${escape(t.name)}</option>`).join('')}</select></label><label>Oefenvorm<select id="mode-filter">${modes.filter(m=>m[0]!=='Gatenlijst').map(m=>`<option ${mode===m[0]?'selected':''}>${m[0]}</option>`).join('')}</select></label></div>${message?`<div class="notice">${escape(message)}</div>`:''}${t?`<div class="trainer-grid"><section class="chat-panel"><div class="chat-head"><b>${escape(t.name)}</b><span>${round.phase==='follow'?'Juryvraag':round.phase==='done'?'Ronde afgerond':'Jouw beurt'}</span></div><div class="messages" role="log" aria-label="Oefengesprek">${round.messages.map(m=>`<article class="message ${m.role}"><div class="message-label">${m.role==='user'?'JOUW ANTWOORD':m.role==='feedback'?'ZELFBEOORDELING':'BATTLE TRAINER'}</div><div class="message-text">${escape(m.text)}</div>${m.ref?`<div class="source-tags">${refButton(m.ref)}</div>`:''}</article>`).join('')}</div>${['answer','follow'].includes(round.phase)?`<form class="answer-form"><label class="sr-only" for="answer">Jouw antwoord</label><textarea id="answer" placeholder="Jouw antwoord. Noem het begrip, leg het uit en gebruik een case uit de stof." required maxlength="6000">${escape(round.draft||'')}</textarea><div class="answer-actions"><div class="helpers"><button type="button" class="btn quiet" id="hint">Weet ik niet</button><button type="button" class="btn quiet" id="explain">Uitleg</button></div><button class="btn dark">${round.phase==='follow'?'Verdedig je antwoord':'Antwoord indienen'} →</button></div></form>`:round.phase==='assess'?rubric(t):`<div class="answer-form"><div class="answer-actions"><button class="btn quiet" id="explain">Uitleg</button><button class="btn primary" id="next">Volgende ${mode==='Battle'?'Battle':'vraag'} →</button></div></div>`}</section>${trainerRail(t)}</div>`:`<button class="btn primary" id="next">Start een ronde →</button>`}${commandForm()}`;let log=app.querySelector('.messages');if(log)log.scrollTop=log.scrollHeight;}
function trainerRail(t){return `<aside class="right-rail"><section class="panel"><div class="eyebrow">DE SPELREGELS</div><h3>Geen punten voor bluf.</h3><p>Gebruik alleen namen, cases en cijfers uit de stof. Vraag “Uitleg” voor het volledige antwoord.</p><div class="source-tags">${refButton(t.id)}</div><p style="margin-top:15px">De vragen zijn oefenvragen. De geheime Battle-vragen zijn niet bekend.</p></section><section class="panel"><div class="eyebrow">DE MEETLAT</div><h3>Kennis <span style="color:var(--muted)">/ 5</span></h3><p>1 · fout of afwezig<br>2 · genoemd<br>3 · goed uitgelegd<br>4 · met case uit de stof<br>5 · met koppeling tussen de vakken</p><h3>Inzicht <span style="color:var(--muted)">/ 5</span></h3><p>1 · herhaling<br>3 · redenering die standhoudt<br>5 · tegenvoorbeeld weerlegd</p></section><div class="notice">Je antwoord wordt bewaard. Jij beoordeelt wat inhoudelijk klopt; de app rekent je score uit.</div></aside>`;}
function rubric(t){let criteria=criteriaFor(t);return `<form class="rubric"><div class="eyebrow">TOETS JE ANTWOORD · ${escape(t.ref)}</div><h3>Wat stond er echt in je antwoord?</h3><p class="saved-note">Vink alleen aan wat je goed hebt onderbouwd. Deze controlepunten zijn gebaseerd op de les en de bijbehorende goede antwoorden. Ze zijn geen automatische beoordeling.</p>${criteria.map((c,i)=>`<label><input type="checkbox" name="criterion-${i}"><span>${escape(c)}</span></label>`).join('')}<hr style="border:0;border-top:1px solid var(--line)">${[['concept','Het relevante begrip correct genoemd.'],['explanation','Het begrip correct uitgelegd in eigen woorden.'],['example','Een passend voorbeeld uit de stof uitgewerkt.'],['connection','Een inhoudelijke koppeling tussen beide vakgebieden gemaakt.'],['reasoning','Een eigen redenering gegeven die standhoudt.'],['counter','Een tegenvoorbeeld besproken én weerlegd.']].map(([key,label])=>`<label><input type="checkbox" name="${key}"><span>${label}</span></label>`).join('')}<button class="btn dark">Bewaar mijn beoordeling →</button><button type="button" class="btn quiet" id="explain">Uitleg</button><p class="saved-note">Bij twijfel kun je de oorspronkelijke les lezen en daarna opnieuw oefenen.</p></form>`;}
const secondCriteria={d1:['Ecologische dimensie als fundament','Sociale en economische dimensies','Onderlinge wisselwerking'],d2:['Veilige operationele ruimte','Ecologische stabiliteit en veerkracht','Gevolgen voor voedsel, water of samenleving'],d3:['Gebruik in plaats van bezit','Prikkel voor levensduur en terugname','MUD Jeans of een andere passende case'],d4:['Minder ijs betekent minder reflectie','Meer opname van warmte','Versterkende terugkoppeling'],d5:['Input en output van kapitalen','Samenwerking, kennis en biogrondstoffen','Waarde naast financieel rendement'],d6:['Beperken van schade versus herstel','Biodiversiteit of energie-positiviteit','Life’s Principles en lokale afstemming'],d7:['Variabelen en causale relaties','Versterkende en dempende loops','Hefboompunt en onbedoelde effecten'],d8:['Piekvraag en piekproductie','Planning en flexibiliteit','Invloed op meerdere terugkoppelingen'],d9:['Relaties en systeemgrenzen','Alle levenscyclusfasen','Totale effecten in plaats van één fase'],e1:['Commons: gezamenlijke hulpbron','Externaliteiten: afwenteling van kosten','Een passend voorbeeld van elk'],e2:['Beperkte maar aanwezige agency','Een vraag, vertraging of afwijking','Groepsnorm zichtbaar en bespreekbaar maken'],e3:['Schaal en efficiëntie','Lobby, standaarden of data','Van marktdeelname naar invloed op spelregels'],e4:['Circulariteit en materiaalstromen','Technologie structureert keuzes','Afweging van macht, controle en verantwoordelijkheid'],e5:['Path dependency als verklaring','Communicatie en prestaties uit elkaar','Verantwoordelijkheid voor transparantie blijft']};
function submitAnswer(text){if(!round)return;round.draft='';if(normalize(text)==='weet ik niet'){hint();return}addMessage('user',text);round.answers.push(text);const t=getTopic(round.topic);if(mode==='Battle'&&round.phase==='answer'){addMessage('trainer',`De jury valt aan:\n1. Bewijs: welk concreet detail uit de case draagt je conclusie?\n2. Kader: welk kader uit ${t.ref} maakt je afweging controleerbaar?\n3. Tegenvoorbeeld: ${counterexample[t.id]}\n\nVervolgvraag: ${t.follow}`,t.id);round.phase='follow';}else{round.phase='assess';}persist();render();}
function assess(form){const t=getTopic(round.topic),flags=Object.fromEntries(['concept','explanation','example','connection','reasoning','counter'].map(k=>[k,form.elements[k].checked]));const criteria=criteriaFor(t);const present=criteria.filter((_,i)=>form.elements['criterion-'+i].checked),missing=criteria.filter((_,i)=>!form.elements['criterion-'+i].checked);const result=score(flags);const reasonsK=['','Het begrip was fout of afwezig.','Je noemde het begrip, maar legde het niet goed uit.','Je legde het begrip correct uit.','Je legde het begrip uit en werkte een voorbeeld uit de stof uit.','Je voegde een inhoudelijke koppeling tussen beide vakgebieden toe.'];const reasonI=result.insight===5?'Je redenering hield stand en je weerlegde ook een tegenvoorbeeld.':result.insight===3?'Je gaf een eigen redenering die standhield.':'Je bleef bij de stelling of gaf nog geen houdbare redenering.';let feedback=`Volgens jouw zelfbeoordeling:\nKlopte: ${present.length?present.join('; '):'geen controlepunt als voldoende aangemerkt'}.\nOntbrak: ${missing.length?missing.join('; '):'geen van de geselecteerde controlepunten'}.\nKennis ${result.knowledge}/5: ${reasonsK[result.knowledge]}\nInzicht ${result.insight}/5: ${reasonI}`;addMessage('feedback',feedback,t.id);state.history.push({topic:t.id,mode,date:new Date().toISOString(),...result,flags,present,missing,answers:round.answers});for(let c of missing)if(!state.gaps.some(g=>g.topic===t.id&&g.point===c))state.gaps.push({topic:t.id,point:c});state.gaps=state.gaps.filter(g=>g.topic!==t.id||!present.includes(g.point));round.phase='done';round.assessment=result;persist();render();}
function hint(){const t=getTopic(round.topic);addMessage('trainer',t.ref+'.',t.id);persist();render();}
function explain(){if(round?.mode==='Quiz'){if(round.phase==='quiz'){message='Kies eerst een antwoord; daarna krijg je de uitleg.';render();return}render();return}if(!round){message='Er is nog geen laatste vraag. Start eerst een oefenronde.';render();return}const t=getTopic(round.topic);let txt=t.answer;if(mode==='Battle')txt+='\n\nEen volledig standpunt benoemt bewijs, het passende kader en een grens of tegenvoorbeeld.';addMessage('trainer',txt,t.id);persist();render();}
function gaps(){app.innerHTML=heading('JOUW AANDACHTSPUNTEN','Van gaten naar grip.','Hier staan ontbrekende controlepunten uit open rondes en fout beantwoorde quizvragen. Beantwoord een quizvraag later goed om dat aandachtspunt te verwijderen.')+(state.gaps.length?state.gaps.map((g,i)=>`<article class="gap-row"><div><h3>${escape(g.point)}</h3><small>${escape(getTopic(g.topic).name)} · ${escape(getLesson(g.topic).ref)}</small></div><div><button class="btn quiet" data-source="${g.topic}">Lees na ↗</button> <button class="btn primary" data-practice="${g.topic}" data-practice-mode="${g.point.startsWith('Quiz: ')?'Quiz':'Overhoor'}">Oefen →</button></div></article>`).join(''):`<div class="empty"><h2>Nog geen gaten vastgelegd.</h2><p>Na een oefenronde beoordeel je wat klopte en wat ontbrak. De ontbrekende punten komen hier terecht.</p><button class="btn primary" data-mode="Overhoor">Begin met overhoren →</button></div>`)+commandForm();}
function scores(){const avg=key=>state.history.length?(state.history.reduce((s,h)=>s+h[key],0)/state.history.length).toFixed(1):'—';app.innerHTML=quizStats()+heading('MIJN VOORTGANG','Zie waar je staat.','Kennis en inzicht horen bij open antwoorden en jouw zelfbeoordeling. Quizresultaten staan apart; ze voorspellen de juryuitslag niet.')+`<div class="stats"><section class="panel"><div class="eyebrow">BEOORDEELDE RONDES</div><div class="stat-value">${state.history.length}</div></section><section class="panel"><div class="eyebrow">GEMIDDELDE KENNIS</div><div class="stat-value">${avg('knowledge')} <small style="font-size:15px">/ 5</small></div></section><section class="panel"><div class="eyebrow">GEMIDDELDE INZICHT</div><div class="stat-value">${avg('insight')} <small style="font-size:15px">/ 5</small></div></section></div>`+(state.history.length?`<div class="table-scroll"><table><thead><tr><th>Onderwerp</th><th>Bron</th><th>Vorm</th><th>Kennis</th><th>Inzicht</th></tr></thead><tbody>${state.history.slice().reverse().map(h=>`<tr><td>${escape(getTopic(h.topic).name)}</td><td>${escape(getLesson(h.topic).ref)}</td><td>${modes.some(m=>m[0]===h.mode)?h.mode:'Eerdere oefenvorm'}</td><td>${h.knowledge}/5</td><td>${h.insight}/5</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><p>Je scores verschijnen hier na je eerste beoordeelde ronde.</p></div>')+`<div class="answer-actions"><button class="btn quiet" id="export">Exporteer voortgang</button><button class="btn quiet" id="reset">Wis mijn voortgang</button></div><p class="saved-note">Je voortgang blijft op dit apparaat in deze browser. Export bevat je eigen antwoorden en beoordeling.</p>`;}
function sources(query=''){let q=normalize(query);const found=lessons.filter(l=>!q||normalize(l.title+' '+l.ref+' '+l.text).includes(q));app.innerHTML=heading('DE BRON IS DE BAAS','De stof, altijd erbij.','De inhoud is opgehaald uit de gelinkte e-learning. Er waren geen losse stofbestanden beschikbaar in deze chat.')+`<label class="sr-only" for="source-search">Zoek in de stof</label><input class="search" id="source-search" placeholder="Zoek een begrip, auteur of case…" value="${escape(query)}"><div class="source-tags" style="margin-bottom:20px"><span class="tag">9 lessen duurzaamheid</span><span class="tag">5 modules business ethics</span><span class="tag">Bronmoment: 8 oktober 2026</span></div><div class="lesson-grid">${found.map(l=>`<article class="lesson-card"><small>${escape(l.ref)}</small><h3>${escape(l.title)}</h3>${q?`<p style="font-size:12px">${escape(snippet(l.text,q))}</p>`:''}<button class="btn quiet" data-source="${l.id}">Lees de les ↗</button><button class="btn primary" data-practice="${l.id}">Oefen →</button></article>`).join('')}</div>${!found.length?'<p class="notice">Niet gevonden in de geladen stof. Er wordt niets aangevuld uit algemene kennis.</p>':''}<section class="upload"><h3>Eigen aantekeningen</h3><p>Voeg een tekstbestand toe en koppel het aan een les of module. Aantekeningen zijn doorzoekbaar, maar veranderen de vaste oefenvragen niet.</p><label>Les of module <select id="note-ref">${lessons.map(l=>`<option value="${l.id}">${escape(l.ref)}</option>`).join('')}</select></label><label>Bestand (.txt of .md) <input id="note-file" type="file" accept=".txt,.md,text/plain,text/markdown"></label><div id="note-status" role="status"></div>${state.notes.map((n,i)=>`<article><b>${escape(n.name)}</b> · ${escape(getLesson(n.ref).ref)} <button class="btn quiet" data-note="${i}">Lezen</button>${q&&normalize(n.text).includes(q)?`<p>${escape(snippet(n.text,q))}</p>`:''}</article>`).join('')}</section>`;}
function snippet(text,q){let index=normalize(text).indexOf(q);return (index>80?'…':'')+text.slice(Math.max(0,index-80),Math.max(0,index-80)+270)+'…';}
function showSource(id){const l=getLesson(id);document.querySelector('#source-title').textContent=l.title;document.querySelector('#source-ref').textContent=l.ref+' · oorspronkelijke e-learning';document.querySelector('#source-body').textContent=l.text;document.querySelector('#source-link').href=l.url;document.querySelector('#source-link').hidden=false;document.querySelector('#source-modal').showModal();}
function menu(){app.innerHTML=heading('COMMANDO’S','Jij kiest de training.','Klik op een oefenvorm of typ een commando onderaan de pagina.')+`<div class="menu-grid">${[['Menu','Toon alle commando’s.'],['Leer [onderwerp]','Krijg maximaal vijf zinnen uitleg met een voorbeeld en beantwoord daarna een controlevraag.'],['Overhoor [onderwerp of alles]','Beantwoord een open vraag, toets je antwoord en ga door naar de volgende.'],['Quiz [onderwerp of alles]','Kies uit vier antwoorden en krijg meteen feedback, uitleg en de les of module.'],['Battle [onderwerp]','Verdedig een stelling, reageer op drie jury-aanvallen en beoordeel daarna kennis en inzicht.'],['Uitleg','Lees het volledige goede antwoord op de laatste oefening.'],['Gatenlijst','Bekijk ontbrekende controlepunten met de les of module om ze na te lezen.']].map(([a,b])=>`<article><h3>${a}</h3><p>${b}</p></article>`).join('')}</div><div class="notice" style="margin-top:20px"><b>Weet ik niet</b> geeft alleen de les of module als hint. Vrije tekst buiten een ronde zoekt in de stof. Tijdens een ronde telt vrije tekst als je antwoord. De trainer gebruikt vaste, brongebonden oefeningen. Open antwoorden hebben zelfbeoordeling; de Quiz controleert je keuze automatisch. Er is geen AI gekoppeld.</div>${commandForm()}`;}
function runCommand(text){const cmd=parseCommand(text);if(!cmd){if(page==='train'&&round&&['answer','follow'].includes(round.phase))return submitAnswer(text);page='sources';sources(text);bind();return}if(cmd.mode==='Menu')return navigate('menu');if(cmd.mode==='Gatenlijst')return navigate('gaps');if(cmd.mode==='Uitleg'){if(round){mode=round.mode;page='train';explain();}else{navigate('menu');const p=document.createElement('p');p.className='notice';p.textContent='Er is nog geen laatste oefening. Start eerst een ronde.';app.prepend(p)}return}begin(cmd.mode,cmd.query);}
function bind(){app.querySelectorAll('[data-quiz-choice]').forEach(b=>b.onclick=()=>answerQuiz(b.dataset.quizChoice));app.querySelector('#answer')?.addEventListener('input',e=>{round.draft=e.target.value;persist()});app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>begin(b.dataset.mode));app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));app.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>showSource(b.dataset.source));app.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>begin(b.dataset.practiceMode||'Overhoor',b.dataset.practice));app.querySelectorAll('.command-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const x=f.querySelector('input').value.trim();if(x)runCommand(x);});app.querySelector('.answer-form')?.addEventListener('submit',e=>{e.preventDefault();let text=app.querySelector('#answer')?.value.trim();if(text)submitAnswer(text)});app.querySelector('.rubric')?.addEventListener('submit',e=>{e.preventDefault();assess(e.currentTarget)});app.querySelector('#hint')?.addEventListener('click',hint);app.querySelector('#explain')?.addEventListener('click',explain);app.querySelector('#next')?.addEventListener('click',nextRound);app.querySelector('#resume')?.addEventListener('click',()=>{mode=round.mode;subject=round.topic;page='train';render()});app.querySelector('#course-filter')?.addEventListener('change',e=>{filter=e.target.value;subject='alles';nextRound()});app.querySelector('#topic-filter')?.addEventListener('change',e=>{subject=e.target.value;nextRound()});app.querySelector('#mode-filter')?.addEventListener('change',e=>{mode=e.target.value;nextRound()});app.querySelector('#source-search')?.addEventListener('input',e=>{let q=e.target.value,p=e.target.selectionStart;sources(q);bind();let input=app.querySelector('#source-search');input.focus();input.setSelectionRange(p,p)});app.querySelector('#note-file')?.addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;if(!/\.(txt|md)$/i.test(f.name)||f.size>1000000){document.querySelector('#note-status').textContent='Kies een .txt- of .md-bestand kleiner dan 1 MB.';return}const ref=app.querySelector('#note-ref').value;state.notes.push({name:f.name,text:await f.text(),ref});persist();sources();bind();document.querySelector('#note-status').textContent='Aantekeningen toegevoegd.'});app.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{let n=state.notes[+b.dataset.note];document.querySelector('#source-title').textContent=n.name;document.querySelector('#source-ref').textContent=getLesson(n.ref).ref+' · eigen aantekeningen, geen oorspronkelijke cursusbron';document.querySelector('#source-body').textContent=n.text;document.querySelector('#source-link').hidden=true;document.querySelector('#source-modal').showModal()});app.querySelector('#export')?.addEventListener('click',()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='battle-voortgang.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});app.querySelector('#reset')?.addEventListener('click',()=>{if(confirm('Je antwoorden, scores en gatenlijst in deze browser wissen? Je aantekeningen blijven bewaard.')){state.history=[];state.quizHistory=[];state.gaps=[];round=null;persist();render()}});}
const counterexample={"d1":"De verkeerscasus noemt ook gezondheid en economische kosten. Wat als je maatregel op die dimensies nadelig uitpakt?","d2":"De stikstofcasus laat doorwerking naar ecosystemen en beleid zien. Welke grens overschrijdt een uitsluitend economisch argument?","d3":"MUD Jeans richt zich ook op langer gebruik en terugname. Wat mist een redenering die uitsluitend recycling waardeert?","d4":"Duurzame projecten kunnen door netcongestie vertragen. Hoe houdt jouw standpunt rekening met die afhankelijkheid?","d5":"Tata Steel moet effecten op de omgeving meewegen. Welke waarde kan verdwijnen terwijl winst groeit?","d6":"Lotusbladeren zijn inspiratie voor functionele eigenschappen. Wat ontbreekt als je alleen de natuurlijke vorm of grondstof noemt?","d7":"In de plasticrecyclingmarkt beïnvloeden prijs, vraag en schaal elkaar. Welke lock-in overleeft jouw technische oplossing?","d8":"Regionale hubs kunnen groei en sociale werkgelegenheid combineren. Hoe verhoudt die optie zich tot jouw groeikeuze?","d9":"Het lease-model stimuleert langere levensduur. Wat als een ander duurzaamheidsissue toch grote impact of risico heeft?","e1":"De gascrisis vereist een keuze wie niet zonder mag komen. Waar zit de waardeafweging binnen jouw schijnbaar technische antwoord?","e2":"De module beschrijft iemand die een moeilijke vraag stelt. Hoe past die morele moed bij jouw verklaring vanuit systeemdruk?","e3":"ASML leunt ook op specialistische werknemers en specifieke leveranciersinvesteringen. Welk risico blijft buiten een puur aandeelhoudersargument?","e4":"De automatische deur helpt gebruikers, maar wordt bij uitval een afhankelijkheid. Wie draagt dan verantwoordelijkheid?","e5":"De Conscious Collection kan als initiatief goed zijn terwijl het volumemodel intact blijft. Welke informatie mist de claim over het geheel?"};
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home')};document.querySelector('#close-modal').onclick=()=>document.querySelector('#source-modal').close();document.querySelector('#source-modal').addEventListener('click',e=>{if(e.target===e.currentTarget){let r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});render();

function criteriaFor(t){return round.index===0?t.criteria:secondCriteria[t.id];}
